"""Keep generated bytecode out of output scans without hiding text leaks."""

import sys
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
import verify_outputs


class OutputScan(unittest.TestCase):
    def test_ignored_bytecode_does_not_trigger_leak_checks(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            cache = root / "__pycache__"
            cache.mkdir()
            marker = verify_outputs.PRIVATE_MARKERS[0] + " xsec_" + "token"
            (cache / "module.cpython-312.pyc").write_text(marker)
            (root / "legacy.pyc").write_text(marker)
            (root / "answer.md").write_text("Public answer")
            with patch.object(verify_outputs, "ROOT", root), patch.object(
                verify_outputs, "SCAN_PATHS", [root]
            ):
                self.assertEqual(verify_outputs.scan_for_tokens(), [])
                self.assertEqual(verify_outputs.scan_for_private_markers(), [])

    def test_private_marker_in_text_is_still_reported(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / "answer.md").write_text(verify_outputs.PRIVATE_MARKERS[0])
            with patch.object(verify_outputs, "ROOT", root), patch.object(
                verify_outputs, "SCAN_PATHS", [root]
            ):
                self.assertEqual(verify_outputs.scan_for_private_markers(), ["answer.md"])

    def test_signed_token_in_text_is_still_reported(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            answer = root / "answer.md"
            answer.write_text("xsec_" + "token")
            with patch.object(verify_outputs, "ROOT", root), patch.object(
                verify_outputs, "SCAN_PATHS", [answer]
            ):
                self.assertEqual(verify_outputs.scan_for_tokens(), ["answer.md"])


if __name__ == "__main__":
    unittest.main()
